package com.manishrawat.realestate.dao; import com.manishrawat.realestate.util.DBConnection; import java.sql.*; import java.util.*;
public class ActivityDAO { public void log(int uid,String a)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO activity_logs(user_id,action) VALUES(?,?)")){p.setInt(1,uid);p.setString(2,a);p.executeUpdate();}} public List<String> recent()throws Exception{List<String> l=new ArrayList<>();try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT CONCAT(COALESCE(u.name,'System'),' - ',a.action,' (',a.created_at,')') x FROM activity_logs a LEFT JOIN users u ON a.user_id=u.id ORDER BY a.id DESC LIMIT 20")){while(r.next())l.add(r.getString("x"));}return l;} }
